using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioSelectionStatisticsValidation {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Validate(){var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var doc=StudioModelDocument.Import(model,"Assets/SelectionStatisticsFrame.asset");using(var editor=new StudioModelEditor(()=>{})){editor.Load(doc);editor.SelectObject(doc.nodes.FindIndex(n=>n.name=="Body"&&n.mesh));var type=typeof(StudioModelEditor);var mode=type.GetField("mode",F);var weld=type.GetField("weld",F);var cached=(Func<long[]>)type.GetMethod("CountSelectedComponents",F).CreateDelegate(typeof(Func<long[]>),editor);var reference=(Func<long[]>)type.GetMethod("CalculateSelectedComponents",F).CreateDelegate(typeof(Func<long[]>),editor);var changed=(Action<bool>)type.GetMethod("PositionsChanged",F).CreateDelegate(typeof(Action<bool>),editor);var flush=(Action)type.GetMethod("FlushPositionStatistics",F).CreateDelegate(typeof(Action),editor);
 foreach(var kind in new[]{StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face})foreach(bool isWelded in new[]{false,true}){mode.SetValue(editor,kind);weld.SetValue(editor,isWelded);editor.Components.Clear();for(int i=0;i<128;i++)editor.Components.Add(i);var counts=cached();Check(counts.SequenceEqual(reference()),"Count mismatch after mode/weld/selection change");Check(ReferenceEquals(counts,cached()),"Unchanged counts were recalculated");editor.Components.Remove(127);Check(cached().SequenceEqual(reference()),"Count mismatch after selection removal");}
 mode.SetValue(editor,StudioModelEditor.ComponentMode.Vertex);weld.SetValue(editor,true);editor.Components.Clear();var mesh=editor.ActiveMesh;for(int i=0;i<mesh.vertexCount/2;i++)editor.Components.Add(i);cached();var costs=new List<double>();var uncached=new List<double>();for(int i=0;i<50;i++){var timer=Stopwatch.StartNew();cached();if(i>=10)costs.Add(timer.Elapsed.TotalMilliseconds);timer.Restart();reference();if(i>=10)uncached.Add(timer.Elapsed.TotalMilliseconds);}
 var baseline=cached();var points=mesh.vertices;var group=Enumerable.Range(0,points.Length).GroupBy(i=>points[i]).Where(g=>g.Any(editor.Components.Contains)).Take(2).ToArray();foreach(int i in group[1])points[i]=points[group[0].First()];mesh.vertices=points;EditorUtility.SetDirty(mesh);changed(true);Check(ReferenceEquals(baseline,cached()),"Active position gesture did not retain counts");flush();Check(cached().SequenceEqual(reference()),"Completed gesture did not update coincident positions");Check(cached()[0]<baseline[0],"Completed gesture did not recount welded positions");points=mesh.vertices;points[0]+=Vector3.one*.003f;mesh.vertices=points;EditorUtility.SetDirty(mesh);changed(false);Check(cached().SequenceEqual(reference()),"Non-gesture position edit retained stale counts");type.GetMethod("ClearComponentDrawing",F).Invoke(editor,null);Check(cached().SequenceEqual(reference()),"Topology cache reset lost statistics");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../selection-statistics-validation.txt")),checks+" assertions PASS; half-Body selected count cached median ms="+costs.OrderBy(x=>x).ElementAt(costs.Count/2)+" reference median ms="+uncached.OrderBy(x=>x).ElementAt(uncached.Count/2));}}
 public static void Run(){try{Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../selection-statistics-validation.txt")),e.ToString());EditorApplication.Exit(1);}}
}
